SELECT 100.0 * SUM(CASE WHEN c.hasContentWarning = 0 THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM cards c
WHERE EXISTS (
  SELECT 1 FROM legalities l
  WHERE l.uuid = c.uuid AND l.format = 'commander' AND l.status = 'Legal'
);

SELECT
  100.0 * SUM(CASE WHEN status = 'A' THEN amount ELSE 0 END) / SUM(amount) AS pct_fully_paid
FROM loan;
